\title{Exponential Preimage Ambiguity and Common Orbit Suffixes\\in the Parameter-Four Logistic Map}
\author{Aristotle}
\date{July 18, 2026}

\begin{document}
\maketitle

\begin{abstract}
For the logistic map $f(x)=4x(1-x)$, we construct an explicit complete binary family of backward trajectories above every interior target. The inverse branches
\[
L(y)=\frac{1-\sqrt{1-y}}2,\qquad U(y)=\frac{1+\sqrt{1-y}}2
\]
map $(0,1)$ into disjoint halves of $(0,1)$ and satisfy $f\circ L=f\circ U=\operatorname{id}$. An $n$-bit word recursively decodes to an interior seed whose $n$th iterate is a prescribed $y\in(0,1)$. Distinct words produce distinct seeds, yielding an explicit family of cardinality $2^n$. Once these seeds reach $y$, their entire futures coincide: for every $k\geq0$, their $(n+k)$th iterates equal $f^k(y)$. This proves exponential exact-real ambiguity in reconstructing a seed from a delayed orbit suffix. We present constructive algorithms, complexity bounds, numerical examples, and a careful cryptographic interpretation. The result concerns exact real dynamics and does not replace finite-precision or computational security analysis.
\end{abstract}

\section{Introduction}
The logistic family $x\mapsto rx(1-x)$ is a standard model of nonlinear population dynamics and deterministic chaos. At $r=4$, the map has strong sensitivity to initial conditions and a transparent relation to angle doubling. These features have motivated cryptographic constructions in which an orbit supplies pseudorandom-looking values.

Sensitivity describes forward separation; seed recovery is a backward question. At parameter $4$, each generic state has two explicit predecessors. Iterating these choices creates a binary inverse tree. We establish that for every interior target $y$ and depth $n$: every decoded seed stays in $(0,1)$, its $n$th iterate is $y$, different bit words give different seeds, and all resulting trajectories share the same suffix after time $n$.

As $|\bits^n|=2^n$, this gives an exponential lower bound for the $n$-step fiber. The phrase ``lower bound'' is deliberate: the construction injects the binary key space into the fiber. Showing that it exhausts the fiber requires a converse classification of arbitrary preimages.

Cryptographically, the result is an exact-real information statement. If observation begins at time $n$ with an interior state, its entire future suffix is compatible with at least $2^n$ explicit seeds. Quantization, cycle structure, output extraction, and attacker models remain separate matters.

\section{Definitions}

\begin{definition}[Logistic map and iteration]
Define $f:\mathbb{R}\to\mathbb{R}$ by
\[
f(x)=4x(1-x).
\]
Write $f^0(x)=x$ and $f^{n+1}(x)=f(f^n(x))$. For $y\in\mathbb{R}$, define the interior $n$-step fiber
\[
\F_n(y)=\{x\in(0,1):f^n(x)=y\}.
\]
\end{definition}

\begin{definition}[Inverse branches]
For $y\leq1$, define
\[
L(y)=\frac{1-\sqrt{1-y}}2,\qquad
U(y)=\frac{1+\sqrt{1-y}}2.
\]
For $b\in\bits$, put $B_0=L$ and $B_1=U$.
\end{definition}

\begin{definition}[Recursive decoding]
For the empty word set $D_{\varnothing}(y)=y$. If $b=(b_0,\ldots,b_{n-1})\in\bits^n$, define
\[
D_b(y)=B_{b_0}\bigl(D_{(b_1,\ldots,b_{n-1})}(y)\bigr)
=B_{b_0}\circ\cdots\circ B_{b_{n-1}}(y).
\]
Thus the first bit chooses the outermost branch, while the last chooses the predecessor immediately above the target.
\end{definition}

\section{One-step branch geometry}

\begin{lemma}[Right-inverse identity]
For every $y\leq1$ and $b\in\bits$,
\[
f(B_b(y))=y.
\]
\end{lemma}
\begin{proof}
Let $s=\sqrt{1-y}$. Either branch has the form $(1\pm s)/2$, whose complement is $(1\mp s)/2$. Hence
\[
4B_b(y)(1-B_b(y))=(1+s)(1-s)=1-s^2=y.
\]
\end{proof}

\begin{lemma}[Interior preservation and separation]
If $0<y<1$, then
\[
0<L(y)<\frac12<U(y)<1.
\]
Consequently both branches preserve the open unit interval and their images are disjoint.
\end{lemma}
\begin{proof}
The hypothesis implies $0<\sqrt{1-y}<1$. Substitution into the two branch formulas gives every strict inequality.
\end{proof}

\begin{lemma}[Branch injectivity]
Each fixed branch $B_b$ is injective on $(0,1)$.
\end{lemma}
\begin{proof}
Equality under either branch implies equality of $\sqrt{1-x}$ and $\sqrt{1-y}$. Squaring gives $x=y$. Equivalently, $L$ is strictly increasing and $U$ strictly decreasing.
\end{proof}

\begin{remark}
If $B_a(x)=B_b(y)$ for interior $x,y$, disjoint branch images first imply $a=b$. Branch injectivity then gives $x=y$. This recovery-and-cancellation principle drives the full tree argument.
\end{remark}

\section{The binary inverse tree}

\begin{lemma}[Interior decoded states]
For $y\in(0,1)$ and $b\in\bits^n$, one has $D_b(y)\in(0,1)$.
\end{lemma}
\begin{proof}
Induct on word length. The empty word returns $y$. For a nonempty word, the decoded suffix is interior by induction, and either outer branch preserves the interval by the preceding lemma.
\end{proof}

\begin{theorem}[Iterated recovery]
For every $y\in(0,1)$, $n\geq0$, and $b\in\bits^n$,
\[
f^n(D_b(y))=y.
\]
\end{theorem}
\begin{proof}
At depth zero the statement is immediate. Write a nonempty word as $b=(b_0,b')$. Then
\[
D_b(y)=B_{b_0}(D_{b'}(y)).
\]
The right-inverse identity removes the outer branch after one forward update:
\[
f(D_b(y))=D_{b'}(y).
\]
The induction hypothesis removes the remaining branches.
\end{proof}

\begin{theorem}[Injective binary decoding]
For fixed $y\in(0,1)$ and $n\geq0$, the map
\[
D_{n,y}:\bits^n\longrightarrow(0,1),\qquad b\longmapsto D_b(y),
\]
is injective.
\end{theorem}
\begin{proof}
Induct on $n$. There is only one empty word. Suppose $D_a(y)=D_b(y)$ at positive depth. If $a_0\neq b_0$, one decoded value lies below $1/2$ and the other above it, a contradiction. Thus $a_0=b_0$. Cancel the common injective outer branch. The decoded suffixes agree, so the induction hypothesis makes all remaining bits equal. Hence $a=b$.
\end{proof}

\begin{theorem}[Exponential preimage family]
For every $y\in(0,1)$ and $n\geq0$, recursive decoding defines an explicit injection
\[
D_{n,y}:\bits^n\hookrightarrow\F_n(y).
\]
In particular,
\[
|\F_n(y)|\geq2^n.
\]
The $2^n$ indexed values are pairwise distinct, interior, and have $n$th iterate $y$.
\end{theorem}
\begin{proof}
Interior membership follows from the interior-decoding lemma, fiber membership from iterated recovery, and injectivity from the preceding theorem. The binary word set has cardinality $2^n$ because each of its $n$ positions has two independent choices.
\end{proof}

\begin{corollary}[Two distinct colliding seeds]
If $n>0$ and $y\in(0,1)$, there exist distinct $x_0,x_1\in(0,1)$ such that
\[
f^n(x_0)=f^n(x_1)=y.
\]
\end{corollary}
\begin{proof}
Decode the all-zero and all-one words. Positive length makes the words distinct, injectivity separates their seeds, and iterated recovery sends both to $y$.
\end{proof}

\section{Common suffixes and ambiguity}

\begin{theorem}[Common orbit suffix]
For $y\in(0,1)$, $n,k\geq0$, and $b\in\bits^n$,
\[
f^{n+k}(D_b(y))=f^k(y).
\]
\end{theorem}
\begin{proof}
Using $f^{n+k}=f^k\circ f^n$ and iterated recovery,
\[
f^{n+k}(D_b(y))=f^k(f^n(D_b(y)))=f^k(y).
\]
\end{proof}

\begin{corollary}[Exponential suffix ambiguity]
If an observer sees the exact suffix
\[
(y,f(y),f^2(y),\ldots)
\]
beginning at time $n$, then at least $2^n$ distinct interior seeds are compatible with the entire suffix.
\end{corollary}
\begin{proof}
The exponential preimage theorem supplies the seeds; the common-suffix theorem makes every later state agree term by term.
\end{proof}

This is an information-theoretic exact-real statement. It assumes observation of $y$ itself, not a rounded state or derived symbol. It does not assert that every cryptographic key is represented, nor that side information cannot separate candidates.

\section{Algorithms and complexity}

\subsection{Decoding one word}
Given $y$ and $b_0,\ldots,b_{n-1}$, evaluate the nested branches from the final bit backward:
\begin{enumerate}[label=\arabic*.]
\item Validate $0<y<1$ and set $x\leftarrow y$.
\item For $j=n-1,n-2,\ldots,0$, replace $x$ by $(1-\sqrt{1-x})/2$ if $b_j=0$, and by $(1+\sqrt{1-x})/2$ if $b_j=1$.
\item Return $x$.
\end{enumerate}
This uses $n$ square roots, $O(n)$ arithmetic operations, and $O(1)$ auxiliary storage. Numerical evaluation introduces rounding, while exact symbolic expressions may grow.

\subsection{Enumerating the family}
One may enumerate integers from $0$ to $2^n-1$, convert each to an $n$-bit word, and decode. This costs $O(n2^n)$ time and $O(2^n)$ output storage. A breadth-first implementation replaces each frontier value $z$ by $L(z)$ and $U(z)$. It evaluates every tree edge once, requiring $O(2^n)$ arithmetic operations and $O(2^n)$ frontier storage. Exponential output cost is unavoidable when all $2^n$ seeds are listed.

\subsection{Numerical verification}
Apply $f$ exactly $n$ times to each generated seed and compare with $y$, then compare later iterates with the orbit beginning at $y$. Floating-point comparisons require a tolerance. High precision is advisable because inverse square roots and forward chaotic expansion can magnify rounding error.

\section{Examples}

\begin{example}[One-step split]
For $y=3/4$, one has $\sqrt{1-y}=1/2$ and
\[
L(3/4)=1/4,\qquad U(3/4)=3/4.
\]
Both map to $3/4$ because $4(1/4)(3/4)=3/4$ and $f(x)=f(1-x)$.
\end{example}

\begin{example}[Depth three]
For any interior $y$, the eight words in $\bits^3$ decode to eight distinct seeds satisfying $f^3(x)=y$. The first bit is read from the seed's side of $1/2$. After one forward update, the second bit is read in the same way, and then the third. This operationally explains injectivity.
\end{example}

\begin{example}[Shared future]
For different depth-$n$ words $a,b$, let $x_a=D_a(y)$ and $x_b=D_b(y)$. Although $x_a\neq x_b$, for every $m\geq0$,
\[
\bigl(f^n(x_a),\ldots,f^{n+m}(x_a)\bigr)
=
\bigl(f^n(x_b),\ldots,f^{n+m}(x_b)\bigr)
=
\bigl(y,\ldots,f^m(y)\bigr).
\]
Rounded numerical experiments show approximate rather than literal equality.
\end{example}

\section{Cryptographic interpretation}
Each backward step contributes one unresolved binary choice. A delay of $n$ steps hides an $n$-bit branch history among $2^n$ explicit candidates. Once histories coalesce at $y$, no later exact orbit state can recover those choices. This obstructs unique seed reconstruction from a delayed exact orbit suffix.

The conclusion is not a general security theorem. A cipher additionally needs a key encoding, message and output models, encryption and decryption algorithms, and an attacker game. Ambiguity does not by itself imply semantic security.

Exact real numbers are also not ordinary machine states. Fixed-point or floating-point dynamics live on finite sets, so every orbit is eventually periodic; branches can merge under rounding and algebraic identities can incur error. Quantized output may increase ambiguity, while auxiliary leakage may reduce it. These implementation effects require a separate model.

The interior hypothesis is essential. At $y=1$, the two formulas coincide at the critical point $1/2$, and at $y=0$ one-step predecessors include boundary points. The clean binary count therefore does not automatically extend to boundary targets.

\section{Angle doubling and further structure}
The identity
\[
f(\sin^2\theta)=4\sin^2\theta\cos^2\theta=\sin^2(2\theta)
\]
explains the binary inverse geometry: reversing one update corresponds to halving an angle, with sign and periodicity choices obscured by the squared sine. When $y=\sin^2\theta$, this suggests expressions
\[
\sin^2\left(\frac{\pm\theta+k\pi}{2^n}\right).
\]
The recursive construction avoids choosing a global angle and makes interval preservation immediate. Identifying both descriptions exactly would sharpen the full fiber classification.

Further work includes proving that every interior preimage has a unique branch word; measuring branch collapse under specified finite-precision rules; embedding suffix ambiguity in a stream-cipher security game; classifying boundary fibers; and combining branch Jacobians with transfer operators to derive the invariant density
\[
\rho(x)=\frac{1}{\pi\sqrt{x(1-x)}}
\]
and Lyapunov exponent $\log 2$.

\section{Itinerary recovery before coalescence}
The injectivity proof has an operational converse for the constructed family. If $x=D_b(y)$, then for every $0\leq j<n$,
\[
b_j=\begin{cases}0,&f^j(x)<1/2,\\1,&f^j(x)>1/2.\end{cases}
\]
Indeed, repeated cancellation gives $f^j(D_b(y))=D_{(b_j,\ldots,b_{n-1})}(y)$, whose outer branch is $B_{b_j}$. Branch separation places this state strictly on the corresponding side of $1/2$. Thus branch information remains readable before time $n$ but is absent from the common suffix beginning at time $n$.

\section{Computational conditioning}
Although the identities are exact, numerical evaluation has conditioning issues. For $0<y<1$,
\[
|L'(y)|=|U'(y)|=\frac{1}{4\sqrt{1-y}},
\]
which grows near $y=1$. Forward iteration has derivative $f'(x)=4-8x$, of magnitude as large as $4$, and can amplify seed-rounding error. Useful diagnostics are the recovery residual
\[
R_b=|f^n(D_b(y))-y|
\]
and suffix residual
\[
S_b(m)=\max_{0\leq k\leq m}|f^{n+k}(D_b(y))-f^k(y)|.
\]
Both vanish in exact arithmetic; nonzero numerical values measure accumulated rounding.

\section{Applications and research program}
The inverse tree describes latent histories in nonlinear state estimation, finite itineraries in symbolic dynamics, backward-orbit sampling in computational dynamics, and discrete historical choices in information theory. Each application requires its own surrounding assumptions.

Natural extensions are: exact classification of the entire interior fiber; equivalence with closed angle-halving formulas; branch-collapse analysis under fixed precision; a stream-cipher security game incorporating suffix ambiguity; boundary-fiber formulas at $0$ and $1$; and measure-theoretic derivation of the invariant arcsine density and Lyapunov exponent from inverse-branch Jacobians.

\section{Conclusion}
The parameter-four logistic map has explicit binary inverse geometry. Every interior target has two separated interior predecessors, each branch is injective, and recursive branch selection sends every $n$-bit word to a distinct depth-$n$ seed. Thus each interior $n$-step fiber contains an indexed family of $2^n$ points. All reach the target after $n$ updates and share its future thereafter.

Forward sensitivity emphasizes trajectory separation; the inverse tree shows that one observed future can be compatible with exponentially many pasts. This structure is mathematically exact, algorithmically constructive, and pertinent to cryptographic observability when kept distinct from finite implementation and computational security.

