from itertools import product
from math import sqrt

def f(x: float) -> float:
    return 4.0*x*(1.0-x)

def decode(y: float, bits: tuple[int, ...]) -> float:
    for bit in reversed(bits):
        y = (1.0 + (1.0 if bit else -1.0)*sqrt(1.0-y))/2.0
    return y

def iterate(x: float, n: int) -> float:
    for _ in range(n): x = f(x)
    return x

