from math import sqrt
from typing import Sequence

def decode_inverse_word(target: float, bits: Sequence[int]) -> float:
    if not 0.0 < target < 1.0:
        raise ValueError("target must be interior")
    x = target
    for bit in reversed(bits):
        if bit not in (0, 1): raise ValueError("nonbinary digit")
        x = (1.0 + (1.0 if bit else -1.0)*sqrt(1.0-x))/2.0
    return x

from math import sqrt

def enumerate_preimage_frontier(target: float, depth: int) -> list[float]:
    if not 0.0 < target < 1.0 or depth < 0:
        raise ValueError("invalid target or depth")
    frontier = [target]
    for _ in range(depth):
        next_frontier: list[float] = []
        for y in frontier:
            s = sqrt(1.0-y)
            next_frontier.extend(((1.0-s)/2.0, (1.0+s)/2.0))
        frontier = next_frontier
    return frontier

from typing import Callable

def recover_itinerary(seed: float, depth: int,
                      update: Callable[[float], float] = lambda x: 4.0*x*(1.0-x)) -> tuple[int, ...]:
    if not 0.0 < seed < 1.0 or depth < 0:
        raise ValueError("invalid seed or depth")
    bits: list[int] = []
    x = seed
    for _ in range(depth):
        if x == 0.5: raise ValueError("critical-point itinerary is ambiguous")
        bits.append(0 if x < 0.5 else 1)
        x = update(x)
    return tuple(bits)

